import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';

const Profile = () => {
  const { id } = useParams();
  const { user: currentUser, updateUser } = useAuth();
  const navigate = useNavigate();
  const [profileUser, setProfileUser] = useState(null);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isFollowing, setIsFollowing] = useState(false);
  
  // Edit states
  const [isEditing, setIsEditing] = useState(false);
  const [editName, setEditName] = useState('');
  const [editBio, setEditBio] = useState('');

  const userId = id || currentUser?.id;
  const isOwnProfile = currentUser && userId === currentUser.id;

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }
    if (!userId) {
      navigate(`/profile/${currentUser.id}`);
      return;
    }
    fetchProfile();
  }, [userId]);

  const fetchProfile = async () => {
    setLoading(true);
    try {
      const userRes = await axios.get(`http://localhost:5000/api/users/${userId}`);
      setProfileUser(userRes.data);
      setEditName(userRes.data.name || '');
      setEditBio(userRes.data.bio || '');
      
      const postsRes = await axios.get(`http://localhost:5000/api/posts/user/${userId}`);
      setPosts(postsRes.data);
      
      if (currentUser) {
        setIsFollowing(userRes.data.followers?.includes(currentUser.id));
      }
    } catch (err) {
      console.error('Error:', err);
    }
    setLoading(false);
  };

  const handleFollow = async () => {
    try {
      const res = await axios.put(`http://localhost:5000/api/users/follow/${userId}`);
      setIsFollowing(!isFollowing);
      setProfileUser(prev => ({
        ...prev,
        followers: isFollowing 
          ? prev.followers?.filter(uid => uid !== currentUser.id) || []
          : [...(prev.followers || []), currentUser.id]
      }));
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleUpdateProfile = async () => {
    try {
      const res = await axios.put('http://localhost:5000/api/users/profile', {
        name: editName,
        bio: editBio
      });
      
      updateUser(res.data);
      setProfileUser(prev => ({ ...prev, name: res.data.name, bio: res.data.bio }));
      setIsEditing(false);
      alert('✅ Profile updated!');
    } catch (err) {
      console.error('Error:', err);
      alert('❌ Update failed');
    }
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (!profileUser) return <div className="loading">User not found</div>;

  return (
    <div className="profile-container">
      {/* Profile Header */}
      <div className="profile-header">
        <img 
          src={profileUser.profilePicture || '/default-avatar.png'} 
          alt="Profile" 
          className="profile-avatar-large"
        />
        <div className="profile-info">
          <h2>{profileUser.name || profileUser.username}</h2>
          <p>@{profileUser.username}</p>
          
          <div className="profile-stats">
            <span>📊 {profileUser.followers?.length || 0} Followers</span>
            <span>📊 {profileUser.following?.length || 0} Following</span>
            <span>📝 {posts.length} Posts</span>
          </div>

          {/* Bio */}
          <div className="profile-bio">
            {profileUser.bio ? (
              <p>{profileUser.bio}</p>
            ) : (
              <p style={{ color: '#999' }}>No bio yet</p>
            )}
          </div>

          {/* Buttons */}
          <div className="profile-buttons">
            {isOwnProfile ? (
              <button 
                className="edit-btn"
                onClick={() => setIsEditing(!isEditing)}
              >
                {isEditing ? '❌ Cancel' : '✏️ Edit Profile'}
              </button>
            ) : (
              <button 
                className={`follow-btn ${isFollowing ? 'following' : ''}`}
                onClick={handleFollow}
              >
                {isFollowing ? 'Following' : '+ Follow'}
              </button>
            )}
          </div>

          {/* Edit Form */}
          {isEditing && isOwnProfile && (
            <div className="edit-form">
              <input
                type="text"
                placeholder="Your name"
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                className="edit-input"
              />
              <textarea
                placeholder="Your bio"
                value={editBio}
                onChange={(e) => setEditBio(e.target.value)}
                className="edit-textarea"
                rows="3"
              />
              <button className="save-btn" onClick={handleUpdateProfile}>
                💾 Save Changes
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Posts */}
      <div className="profile-posts">
        <h3>Posts</h3>
        {posts.length === 0 ? (
          <p>No posts yet</p>
        ) : (
          posts.map(post => (
            <PostCard 
              key={post._id} 
              post={post} 
              onUpdate={fetchProfile}
              onDelete={fetchProfile}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default Profile;
